public sealed partial class AgentRpcProviderReference<TClient> : IRetirableAgentRpcReference
    where TClient : class
{
    private readonly ISunderRpcClient _client;
    private readonly CancellationTokenSource _retirement = new();
    private readonly TClient _binding;
    private int _retired;

    internal AgentRpcProviderReference(
        ISunderRpcClient client,
        AgentRpcProviderService<TClient> service,
        SunderRpcProviderSnapshot provider)
    {
        _client = client;
        Provider = provider;
        _binding = service.CreateClient(client, provider);
    }

    public SunderRpcProviderSnapshot Provider { get; }
    public string PackageId => Provider.PackageId;
    public string ProviderId => Provider.ProviderId;

    internal bool CanReuse(SunderRpcProviderSnapshot provider)
        => !_retirement.IsCancellationRequested
           && AgentRpcProviderHandle.From(Provider).Matches(provider);

    public bool TryAcquire([NotNullWhen(true)] out AgentRpcLease<TClient>? lease)
    {
        if (_retirement.IsCancellationRequested)
        {
            lease = null;
            return false;
        }
        SunderRpcProviderSnapshot? current;
        try
        {
            current = _client.GetProviderAsync(Provider.Endpoint, _retirement.Token).AsTask().GetAwaiter().GetResult();
        }
        catch (OperationCanceledException)
        {
            lease = null;
            return false;
        }
        catch (SunderRpcException exception) when (
            exception.Error.Kind is SunderRpcErrorKind.StaleEndpoint or SunderRpcErrorKind.Unavailable)
        {
            if (exception.Error.Kind == SunderRpcErrorKind.StaleEndpoint) Retire();
            lease = null;
            return false;
        }
        if (current is null
            || current.State != SunderRpcProviderState.Active
            || !AgentRpcProviderHandle.From(Provider).Matches(current))
        {
            Retire();
            lease = null;
            return false;
        }
        lease = new AgentRpcLease<TClient>(Provider.PackageId, _binding, _retirement.Token);
        return true;
    }

    void IRetirableAgentRpcReference.Retire() => Retire();

    private void Retire()
    {
        if (Interlocked.Exchange(ref _retired, 1) != 0) return;
        try
        {
            _retirement.Cancel();
        }
        catch
        {
            // Retirement observers cannot break catalog reconciliation.
        }
        try
        {
            (_binding as IDisposable)?.Dispose();
        }
        catch
        {
            // Retired client cleanup cannot break catalog reconciliation.
        }
    }
}

