public enum AgentRpcCatalogAvailability
{
    Unknown,
    Available,
    Unavailable,
    PermissionDenied,
    Faulted,
}

public sealed record AgentRpcProviderHandle(
    string PackageId,
    string PackageVersion,
    string ProviderId,
    string ContractId,
    string ContractVersion,
    string ContractSha256,
    Guid ActivationId,
    long ActivationEpoch,
    long SessionGeneration,
    string EndpointReference)
{
    internal static AgentRpcProviderHandle From(SunderRpcProviderSnapshot provider)
        => new(
            provider.PackageId,
            provider.PackageVersion,
            provider.ProviderId,
            provider.ContractId,
            provider.ContractVersion,
            provider.ContractSha256,
            provider.ActivationId,
            provider.ActivationEpoch,
            provider.SessionGeneration,
            provider.Endpoint.Value);

    internal bool Matches(SunderRpcProviderSnapshot provider)
        => string.Equals(PackageId, provider.PackageId, StringComparison.Ordinal)
           && string.Equals(PackageVersion, provider.PackageVersion, StringComparison.Ordinal)
           && string.Equals(ProviderId, provider.ProviderId, StringComparison.Ordinal)
           && string.Equals(ContractId, provider.ContractId, StringComparison.Ordinal)
           && string.Equals(ContractVersion, provider.ContractVersion, StringComparison.Ordinal)
           && string.Equals(ContractSha256, provider.ContractSha256, StringComparison.Ordinal)
           && ActivationId == provider.ActivationId
           && ActivationEpoch == provider.ActivationEpoch
           && SessionGeneration == provider.SessionGeneration
           && string.Equals(EndpointReference, provider.Endpoint.Value, StringComparison.Ordinal);
}
